export function RseView({ v }: { v: any }) {
  return (
    <>

<div style={{ display: "flex", flexDirection: "column", gap: "14px" } as any}>
<div style={{ display: "flex", flexWrap: "wrap", gap: "6px 22px", padding: "10px 14px", border: "2px solid #0d1815", borderRadius: "8px", background: "#fffaf0", font: "500 14px/1.35 'Helvetica Neue',Helvetica,Arial" } as any}>{(v.steps || []).map((s: any, s_n: number) => (<Fragment key={s_n}><span style={{ flex: "1 1 240px" } as any}><b>{s.n}</b> {s.t}</span></Fragment>))}</div>
<div style={{ font: "700 14px 'Helvetica Neue',Helvetica,Arial" } as any}>{v.rse.hint}</div>
<div style={{ display: "flex", flexWrap: "wrap", gap: "10px", padding: "14px 10px 10px", border: "2px solid #0d1815", borderRadius: "10px", background: "#03383f" } as any}>{(v.rse.deck || []).map((c: any, c_n: number) => (<Fragment key={c_n}><button onClick={c.go} aria-label={`Card ${c.v}`} style={{ all: "unset", cursor: "pointer", boxSizing: "border-box", width: "58px", height: "78px", border: "2px solid #0d1815", borderRadius: "8px", background: `${c.bg}`, boxShadow: `${c.sh}`, transform: `translateY(${c.ty})`, opacity: `${c.op}`, display: "flex", alignItems: "center", justifyContent: "center", font: "800 24px Syne", transition: "transform .12s" } as any}>{c.v}</button></Fragment>))}</div>
<div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(min(100%,150px),1fr))", gap: "14px" } as any}>{(v.rse.animals || []).map((a: any, a_n: number) => (<Fragment key={a_n}><button onClick={a.go} style={{ all: "unset", cursor: "pointer", boxSizing: "border-box", border: "2px solid #0d1815", borderRadius: "10px", background: `${a.bg}`, padding: "12px", display: "flex", flexDirection: "column", alignItems: "center", gap: "8px", boxShadow: "3px 3px 0 #0d1815" } as any}><span style={{ height: "96px", display: "flex", alignItems: "center" } as any}><img src={a.img} alt="" style={{ maxHeight: "96px", maxWidth: "100%" } as any} /></span><b style={{ font: "700 15px 'Helvetica Neue',Helvetica,Arial" } as any}>{a.name}</b><span style={{ minWidth: "44px", height: "30px", border: "2px dashed #0d1815", borderRadius: "6px", background: "#fff", display: "flex", alignItems: "center", justifyContent: "center", font: "800 18px Syne", padding: "0 8px" } as any}>{a.v}</span></button></Fragment>))}</div>
<div style={{ font: "700 14px 'JetBrains Mono'", color: "#03383f" } as any}>{v.rse.order}</div>
</div>
    </>
  );
}

